{"revision":4,"files":[{"path":"slugify.mjs","hash":"b9b50f8b4b7ab5c07f44cb51bb666b2bd66f9f6808cb2e6880d3bb02ea4c7c0a","content":"/**
 * Convert a string to a URL-friendly ASCII slug.
 *
 * @param {string} value
 * @returns {string}
 */
export function slugify(value) {
  if (typeof value !== "string") {
    throw new TypeError("value must be a string");
  }

  return value
    .normalize("NFKD")
    .replace(/\p{M}/gu, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}
