import test from "node:test";
import { spawnSync } from "node:child_process";
import { slugify } from "./slugify.mjs";

test("slugifies the documented examples", () => {
  assert.equal(slugify("Hello, World!"), "hello-world");
  assert.equal(slugify("Café déjà vu"), "cafe-deja-vu");
  assert.equal(slugify("  A__B  "), "a-b");
});

test("returns an empty slug for empty and punctuation-only input", () => {
  assert.equal(slugify(""), "");
  assert.equal(slugify("!?..."), "");
});

test("collapses repeated separators", () => {
  assert.equal(slugify("one --- two___three"), "one-two-three");
});

test("rejects non-string values", () => {
  assert.throws(() => slugify(null), TypeError);
  assert.throws(() => slugify(42), TypeError);
});

test("CLI prints a slug for joined arguments", () => {
  const result = spawnSync(process.execPath, ["cli.mjs", "Hello,", "World!"], {
    encoding: "utf8",
  });

  assert.equal(result.status, 0);
  assert.equal(result.stdout, "hello-world\n");
  assert.equal(result.stderr, "");
});

test("CLI reports usage and fails without arguments", () => {
  const result = spawnSync(process.execPath, ["cli.mjs"], { encoding: "utf8" });

  assert.equal(result.status, 1);
  assert.equal(result.stdout, "");
  assert.match(result.stderr, /usage/i);
});
","mode":420},{"path":"README.md","hash":"fda3f48d1bc9cca1e1c3f220a75a5e2ce58f7918a0783b2fad5fd10d9c948d6b","content":"# Slugifier

A tiny, dependency-free Node.js utility for converting text into URL-friendly slugs.

## API

```js
import { slugify } from './slugify.mjs';

slugify('Café déjà vu'); // 'cafe-deja-vu'
```

`slugify(value)` accepts a string and returns a lowercase slug. It removes Unicode combining marks, turns runs of non-ASCII letters, digits, and separators into a single hyphen, and trims outer hyphens. It throws `TypeError` for non-string values.

Examples:

```js
slugify('Hello, World!'); // 'hello-world'
slugify('  A__B  ');      // 'a-b'
slugify('!!!');           // ''
```

## CLI

Pass text after the command; all arguments are joined with spaces:

```sh
node cli.mjs Café déjà vu
# cafe-deja-vu
```

Run it without arguments to see usage information.

## Tests

```sh
npm test
